const body = $('Webhook').item.json.body || $('Webhook').item.json;

const keyword              = body.query || body.keyword || '';
const search_id            = body.search_id || null;
const supabase_url         = body.supabase_url || '';
const supabase_service_key = body.supabase_service_key || '';
const apify_token          = body.apify_token || '';
const encodedKw            = encodeURIComponent(keyword);

// Una sola URL para Meta Ads Library — devuelve FB + IG juntos
const fbAdsUrl = `https://www.facebook.com/ads/library/?active_status=active&ad_type=all&country=ALL&q=${encodedKw}&search_type=keyword_unordered`;

console.log('Config — keyword:', keyword, '| search_id:', search_id);

return [{
  json: {
    keyword,
    search_id,
    supabase_url,
    supabase_service_key,
    apify_token,
    maxAds:        Math.min(body.max_ads || 50, 50),
    minViews:      body.filters?.min_views || 10000,
    minDuration:   body.filters?.min_duration_seconds || 5,
    maxAgeDays:    body.filters?.max_age_days || 180,
    minDaysActive: body.filters?.min_days_active || 3,
    dna_expert:       body.dna_expert || '',
    dna_audience:     body.dna_audience || '',
    dna_product:      body.dna_product || '',
    telegram_chat_id: body.telegram_chat_id || '',
    email:            body.email || '',
    fbAdsUrl,
  }
}];

// ─── Scraper: Meta Ads Library (FB + IG en una sola sesión) ──────────────────
const config = $('Config').item.json;
const apifyToken = config.apify_token || '';

if (!apifyToken) {
  console.log('apify_token vacío');
  return [{ json: { _platform: 'facebook', _error: 'APIFY_TOKEN no configurado' } }];
}

const maxItems = config.maxAds || 50;
console.log('Meta Ads — keyword:', config.keyword, '| maxItems:', maxItems);

let items = [];
try {
  const results = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/apify~facebook-ads-scraper/run-sync-get-dataset-items?token=${apifyToken}&timeout=60`,
    body: {
      startUrls: [{ url: config.fbAdsUrl }],
      maxItems,
      country: 'ALL',
      activeStatus: 'active',
      sortOrder: 'relevancy_monthly_grouped'
    },
    json: true,
    timeout: 90000
  });
  items = Array.isArray(results) ? results : [];
  console.log(`Meta Ads: ${items.length} obtenidos. Keys:`, items[0] ? Object.keys(items[0]).slice(0,8).join(',') : 'ninguno');
} catch(e) {
  console.log('Meta Ads error:', e.message);
}

return items.length > 0 ? items.map(ad => ({ json: ad })) : [{ json: { _platform: 'facebook', _empty: true } }];

// ─── Scraper: TikTok orgánico por hashtag ────────────────────────────────────
const config = $('Config').item.json;
const apifyToken = config.apify_token || '';

if (!apifyToken) {
  return [{ json: { _platform: 'tiktok', _error: 'APIFY_TOKEN no configurado' } }];
}

const maxItems = config.maxAds || 50;
console.log('TikTok — keyword:', config.keyword, '| maxItems:', maxItems);

let items = [];
try {
  const results = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/clockworks~free-tiktok-scraper/run-sync-get-dataset-items?token=${apifyToken}&timeout=60`,
    body: {
      hashtags: [config.keyword],
      resultsPerPage: maxItems,
      maxItems
    },
    json: true,
    timeout: 90000
  });
  items = Array.isArray(results) ? results : [];
  console.log(`TikTok: ${items.length} obtenidos`);
} catch(e) {
  console.log('TikTok error:', e.message);
}

return items.length > 0 ? items.map(v => ({ json: v })) : [{ json: { _platform: 'tiktok', _empty: true } }];

// ─── Scraper: Instagram orgánico por hashtag ─────────────────────────────────
const config = $('Config').item.json;
const apifyToken = config.apify_token || '';

if (!apifyToken) {
  return [{ json: { _platform: 'ig_organic', _error: 'APIFY_TOKEN no configurado' } }];
}

const hashtag  = config.keyword.replace(/\s+/g, '').replace(/^#/, '');
const maxItems = config.maxAds || 50;
console.log('IG Orgánico — hashtag:', hashtag, '| maxItems:', maxItems);

let items = [];
try {
  const results = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/apify~instagram-hashtag-scraper/run-sync-get-dataset-items?token=${apifyToken}&timeout=60`,
    body: { hashtags: [hashtag], resultsLimit: maxItems },
    json: true,
    timeout: 90000
  });
  items = Array.isArray(results) ? results : [];
  console.log(`IG Orgánico: ${items.length} posts para #${hashtag}`);
} catch(e) {
  console.log('IG Orgánico error:', e.message);
}

return items.length > 0 ? items.map(p => ({ json: p })) : [{ json: { _platform: 'ig_organic', _empty: true } }];

// ─── Filtro: Meta Ads (FB + IG) — proxy = días activo ────────────────────────
const items = $input.all();
const config = $('Config').item.json;
const minDaysActive = config.minDaysActive || 3;
const maxAgeDays    = config.maxAgeDays || 180;
const filtered = [];

for (const item of items) {
  if (item.json._empty || item.json._error) continue;
  const ad = item.json;
  const startDate = ad.startDate || ad.ad_delivery_start_time || ad.start_date || ad.adDeliveryStartTime;
  let daysActive = 0;
  if (startDate) {
    daysActive = Math.floor((Date.now() - new Date(startDate).getTime()) / 86400000);
  }
  if (daysActive >= minDaysActive && daysActive <= maxAgeDays) {
    const quality = daysActive >= 30 ? 'high' : daysActive >= 14 ? 'medium' : 'low';
    // Detectar si es IG o FB por publisherPlatforms
    const platforms = ad.publisherPlatforms || ad.publisher_platforms || [];
    const isIG = Array.isArray(platforms) ? platforms.includes('instagram') : String(platforms).includes('instagram');
    const platform = isIG ? 'instagram_ads' : 'facebook';
    filtered.push({
      json: {
        ...ad,
        _daysActive: daysActive,
        _platform: platform,
        _qualitySignal: quality,
        _adText: ad.adText || ad.ad_creative_bodies?.[0] || ad.body || ad.snapshot?.body?.markup?.__html || '',
        _adLink: ad.adUrl || ad.ad_snapshot_url || `https://www.facebook.com/ads/library/?id=${ad.adArchiveID || ad.id}`
      }
    });
  }
}

filtered.sort((a, b) => (b.json._daysActive || 0) - (a.json._daysActive || 0));
const top = filtered.slice(0, 25);
console.log(`Meta Ads filtrados: ${top.length}/${items.length}`);
return top.length > 0 ? top : [{ json: { _platform: 'facebook', _empty: true, _filtered: true } }];

// ─── Filtro: TikTok — views + duración + antigüedad ──────────────────────────
const items = $input.all();
const config = $('Config').item.json;
const MIN_VIEWS    = config.minViews    || 10000;
const MIN_DURATION = config.minDuration || 5;
const MAX_AGE_DAYS = config.maxAgeDays  || 180;
const filtered = [];

for (const item of items) {
  if (item.json._empty || item.json._error) continue;
  const v = item.json;
  const views    = v.playCount || v.plays || v.viewCount || v.stats?.playCount || 0;
  const duration = v.duration  || v.videoLength || v.videoDuration || v.video?.duration || 0;
  const ct = v.createTime || v.createdAt || v.publishedAt;
  let ageInDays = 0;
  if (ct) {
    const created = new Date(typeof ct === 'number' ? ct * 1000 : ct);
    ageInDays = Math.floor((Date.now() - created.getTime()) / 86400000);
  }
  if (views >= MIN_VIEWS && duration >= MIN_DURATION && ageInDays <= MAX_AGE_DAYS && ageInDays > 0) {
    const quality = views >= 1000000 ? 'high' : views >= 100000 ? 'medium' : 'low';
    filtered.push({ json: { ...v, _views: views, _duration: duration, _ageInDays: ageInDays, _platform: 'tiktok', _qualitySignal: quality, _adText: v.text || v.desc || v.description || '', _adLink: v.webVideoUrl || v.shareUrl || '' } });
  }
}

filtered.sort((a, b) => (b.json._views || 0) - (a.json._views || 0));
const top = filtered.slice(0, 25);
console.log(`TikTok filtrados: ${top.length}/${items.length}`);
return top.length > 0 ? top : [{ json: { _platform: 'tiktok', _empty: true, _filtered: true } }];

// ─── Filtro: Instagram orgánico ──────────────────────────────────────────────
const items = $input.all();
const config = $('Config').item.json;
const MIN_VIEWS    = config.minViews    || 10000;
const MIN_DURATION = config.minDuration || 5;
const MAX_AGE_DAYS = config.maxAgeDays  || 180;
const filtered = [];

for (const item of items) {
  if (item.json._empty || item.json._error) continue;
  const p = item.json;
  const views    = p.videoViewCount || p.videoPlayCount || p.playCount || p.likesCount || 0;
  const duration = p.videoDuration  || p.video?.duration || p.duration || 0;
  const isVideo  = p.type === 'Video' || p.isVideo || !!p.videoUrl || duration > 0;
  const timestamp = p.timestamp || p.takenAt || p.taken_at || p.createdAt;
  let ageInDays = 0;
  if (timestamp) {
    const created = new Date(typeof timestamp === 'number' ? timestamp * 1000 : timestamp);
    ageInDays = Math.floor((Date.now() - created.getTime()) / 86400000);
  }
  const likes = p.likesCount || p.likeCount || 0;
  const passesFilter = isVideo ? (views >= MIN_VIEWS && duration >= MIN_DURATION) : (likes >= 5000);
  if (passesFilter && ageInDays <= MAX_AGE_DAYS && ageInDays > 0) {
    const quality = isVideo
      ? (views >= 1000000 ? 'high' : views >= 100000 ? 'medium' : 'low')
      : (likes >= 50000 ? 'high' : likes >= 10000 ? 'medium' : 'low');
    filtered.push({
      json: {
        ...p,
        _views: views, _duration: duration, _ageInDays: ageInDays, _isVideo: isVideo,
        _platform: 'ig_organic', _qualitySignal: quality,
        _adText: p.caption || p.text || p.description || '',
        _adLink: p.url || (p.shortCode ? `https://www.instagram.com/p/${p.shortCode}/` : ''),
      }
    });
  }
}

filtered.sort((a, b) => (b.json._views || 0) - (a.json._views || 0));
const top = filtered.slice(0, 25);
console.log(`IG Orgánico filtrados: ${top.length}/${items.length}`);
return top.length > 0 ? top : [{ json: { _platform: 'ig_organic', _empty: true, _filtered: true } }];

const items = $input.all();
const config = $('Config').item.json;

const summary = {
  facebook:      { total: 0, high: 0, medium: 0, low: 0 },
  instagram_ads: { total: 0, high: 0, medium: 0, low: 0 },
  tiktok:        { total: 0, high: 0, medium: 0, low: 0 },
  ig_organic:    { total: 0, high: 0, medium: 0, low: 0 },
};

const validContents = [];

for (const item of items) {
  if (item.json._empty || item.json._error || item.json._filtered) continue;
  const platform = item.json._platform || 'unknown';
  const quality  = item.json._qualitySignal || 'low';
  if (summary[platform]) {
    summary[platform].total++;
    if (summary[platform][quality] !== undefined) summary[platform][quality]++;
  }
  validContents.push({
    platform, quality,
    text:       item.json._adText || '',
    link:       item.json._adLink || '',
    daysActive: item.json._daysActive || 0,
    views:      item.json._views || 0,
    raw:        item.json,
  });
}

const total = validContents.length;
console.log(`Resumen: ${total} contenidos — Meta:${summary.facebook.total+summary.instagram_ads.total} TK:${summary.tiktok.total} IG:${summary.ig_organic.total}`);

return [{
  json: {
    contents: validContents, summary, totalContents: total,
    keyword:              config.keyword,
    search_id:            config.search_id,
    supabase_url:         config.supabase_url,
    supabase_service_key: config.supabase_service_key,
    dna_expert:           config.dna_expert,
    dna_audience:         config.dna_audience,
    dna_product:          config.dna_product,
  }
}];

const { contents, search_id, supabase_url, supabase_service_key } = $input.first().json;

console.log('Guardar en DB — search_id:', search_id, '| contents:', (contents||[]).length);

if (!search_id || !supabase_url || !supabase_service_key) {
  console.log('Sin search_id/supabase — skip. Vals:', { search_id: !!search_id, url: !!supabase_url, key: !!supabase_service_key });
  return [{ json: { done: true, saved: 0, skipped: true } }];
}

const headers = {
  'Authorization': `Bearer ${supabase_service_key}`,
  'apikey': supabase_service_key,
  'Content-Type': 'application/json',
  'Prefer': 'resolution=ignore-duplicates,return=minimal'
};

const toDateStr = (val) => {
  if (!val) return new Date().toISOString().split('T')[0];
  try {
    const d = typeof val === 'number' ? new Date(val * 1000) : new Date(val);
    const s = d.toISOString().split('T')[0];
    return s < '2000-01-01' ? new Date().toISOString().split('T')[0] : s;
  } catch { return new Date().toISOString().split('T')[0]; }
};

let savedCount = 0;

for (const content of (contents || [])) {
  const raw = content.raw || {};
  let adArchiveId, pageId, pageName, pageUrl, pageLikes, adStartDate, daysActive, adType, adLink, mediaUrl;

  if (content.platform === 'facebook' || content.platform === 'instagram_ads') {
    adArchiveId = String(raw.adArchiveID || raw.adArchiveId || raw.id || `meta_${Date.now()}_${Math.random().toString(36).slice(2)}`);
    pageId      = String(raw.pageID || raw.pageId || raw.page_id || 'meta');
    pageName    = raw.pageName || raw.page_name || raw.advertiserName || raw.snapshot?.page_name || 'Meta Ad';
    pageUrl     = raw.pageUrl || raw.page_url || '';
    pageLikes   = Number(raw.pageLikes || raw.page_likes || 0);
    adStartDate = toDateStr(raw.startDate || raw.ad_delivery_start_time || raw.start_date);
    daysActive  = Number(raw._daysActive || content.daysActive || 0);
    adType      = (raw.isVideo || raw.snapshot?.videos?.length > 0) ? 'video' : 'image';
    adLink      = content.link || raw.adUrl || raw.ad_snapshot_url || `https://www.facebook.com/ads/library/?id=${adArchiveId}`;
    mediaUrl    = raw.snapshot?.videos?.[0]?.video_hd_url || raw.snapshot?.images?.[0]?.original_image_url || null;
  } else if (content.platform === 'tiktok') {
    adArchiveId = String(raw.id || raw.videoId || `tk_${Date.now()}_${Math.random().toString(36).slice(2)}`);
    pageId      = String(raw.authorMeta?.id || raw.author?.id || 'tiktok');
    pageName    = raw.authorMeta?.name || raw.author?.nickname || raw.authorMeta?.nickName || 'TikTok';
    pageUrl     = `https://www.tiktok.com/@${raw.authorMeta?.name || raw.author?.uniqueId || ''}`;
    pageLikes   = Number(raw.authorMeta?.fans || raw.authorMeta?.followers || 0);
    adStartDate = toDateStr(raw.createTime);
    daysActive  = Number(raw._ageInDays || content.daysActive || 0);
    adType      = 'video';
    adLink      = content.link || raw.webVideoUrl || raw.shareUrl || '';
    mediaUrl    = raw.videoMeta?.playAddr || raw.video?.playAddr || null;
  } else {
    adArchiveId = String(raw.id || raw.shortCode || `ig_${Date.now()}_${Math.random().toString(36).slice(2)}`);
    pageId      = String(raw.ownerId || raw.owner?.id || 'instagram');
    pageName    = raw.ownerUsername || raw.owner?.username || 'Instagram';
    pageUrl     = `https://www.instagram.com/${raw.ownerUsername || raw.owner?.username || ''}/`;
    pageLikes   = Number(raw.likesCount || raw.likeCount || 0);
    adStartDate = toDateStr(raw.timestamp || raw.takenAt);
    daysActive  = Number(raw._ageInDays || content.daysActive || 0);
    adType      = raw._isVideo ? 'video' : 'image';
    adLink      = content.link || (raw.shortCode ? `https://www.instagram.com/p/${raw.shortCode}/` : '');
    mediaUrl    = raw.videoUrl || raw.displayUrl || null;
  }

  const record = {
    search_id,
    ad_archive_id: adArchiveId,
    page_id:    pageId   || 'unknown',
    page_name:  pageName || 'unknown',
    page_url:   pageUrl  || null,
    page_likes: pageLikes,
    ad_start_date: adStartDate,
    days_active:   daysActive,
    ad_type:       adType,
    original_ad_copy: (content.text || '').slice(0, 5000) || null,
    media_url:   mediaUrl || null,
    media_description: null,
    summary: null,
    raw_data: {
      _platform:   content.platform,
      _quality:    content.quality,
      _views:      content.views || raw._views || 0,
      _adLink:     adLink,
      _daysActive: daysActive,
    }
  };

  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${supabase_url}/rest/v1/ads`,
      headers,
      body: record,
      json: true
    });
    savedCount++;
  } catch(e) {
    console.log(`Error guardando (${content.platform} ${adArchiveId}):`, e.message);
  }
}

const total = (contents || []).length;
try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${supabase_url}/rest/v1/ad_searches?id=eq.${search_id}`,
    headers: { ...headers, 'Prefer': 'return=minimal' },
    body: { status: 'completed', total_results: total, filtered_results: savedCount, completed_at: new Date().toISOString() },
    json: true
  });
} catch(e) {
  console.log('Error actualizando ad_searches:', e.message);
}

console.log(`Guardados ${savedCount}/${total} para search_id=${search_id}`);
return [{ json: { done: true, saved: savedCount, total, search_id } }];
